def branch_db_path(branch_key: str):
    """Return Path to the SQLite file for a given branch."""
    return DATA_ROOT / f"jaa_{branch_key}.db"

def switch_branch_db(branch_key: str):
    """Point _jaa.DB_PATH at the chosen branch — thread-safe via _jaa.get_conn override."""
    import JAA_Timesheet_v17 as _m
    branch_data = DATA_ROOT / branch_key
    branch_data.mkdir(parents=True, exist_ok=True)
    for sub in ["backups", "logs", "documents/t1_forms", "documents/t5_forms",
                "learning/ppts", "learning/pdfs", "learning/docs",
                "learning/excel", "learning/misc", "learning/sops",
                "reimbursements"]:
        (branch_data / sub).mkdir(parents=True, exist_ok=True)
    db_path = branch_data / f"jaa_{branch_key}.db"
    # Store in thread-local so concurrent requests don't overwrite each other
    _db_lock.path       = db_path
    _db_lock.branch_key = branch_key
    # Also set module-level so non-request code (startup) works
    _m.DB_PATH     = db_path
    _m.DATA_DIR    = branch_data
    _m.BACKUP_DIR  = branch_data / "backups"
    _m.LOGS_DIR    = branch_data / "logs"
    _m.DOCS_DIR    = branch_data / "documents"
    _m.T1_DIR      = branch_data / "documents" / "t1_forms"
    _m.T5_DIR      = branch_data / "documents" / "t5_forms"
    _m.LEARN_DIR   = branch_data / "learning"
    _m.CONFIG_FILE = branch_data / "jaa_config.json"


def _get_branch_conn():
    """Open a SQLite connection to the current thread's branch DB."""
    import sqlite3
    path = getattr(_db_lock, 'path', None) or _jaa.DB_PATH
    conn = sqlite3.connect(str(path), timeout=10)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    conn.execute("PRAGMA journal_mode = WAL")
    return conn


def _branch_call(fn, *args, **kwargs):
    """Call a _jaa function after ensuring DB_PATH points to current thread's branch."""
    path = getattr(_db_lock, 'path', None)
    if path:
        _jaa.DB_PATH = path
    return fn(*args, **kwargs)

# Master DB — only for super-admin PIN storage
MASTER_DB_PATH = DATA_ROOT / "jaa_master.db"

def get_master_conn():
    import sqlite3, contextlib
    @contextlib.contextmanager
    def _cm():
        conn = sqlite3.connect(str(MASTER_DB_PATH), timeout=10)
        conn.row_factory = sqlite3.Row
        try:
            yield conn
            conn.commit()
        finally:
            conn.close()
    return _cm()

def init_master_db():
    """Create master DB with super-admin PIN table (PIN 2580 default)."""
    import sqlite3, hashlib
    conn = sqlite3.connect(str(MASTER_DB_PATH))
    conn.execute("""CREATE TABLE IF NOT EXISTS master_pins (
        key      TEXT PRIMARY KEY,
        pin_hash TEXT NOT NULL
    )""")
    conn.commit()
    existing = conn.execute("SELECT key FROM master_pins WHERE key='__superadmin__'").fetchone()
    if not existing:
        h = hashlib.sha256("2580".encode()).hexdigest()
        conn.execute("INSERT INTO master_pins(key,pin_hash) VALUES('__superadmin__',?)", (h,))
        conn.commit()
        print("✓ Super-admin PIN initialised (2580)")
    conn.close()

def verify_superadmin_pin(pin: str) -> bool:
    import sqlite3, hashlib
    h = hashlib.sha256(pin.encode()).hexdigest()
    try:
        conn = sqlite3.connect(str(MASTER_DB_PATH))
        row = conn.execute("SELECT pin_hash FROM master_pins WHERE key='__superadmin__'").fetchone()
        conn.close()
        return row and row[0] == h
    except Exception:
        return False

def change_superadmin_pin(new_pin: str):
    import sqlite3, hashlib
    h = hashlib.sha256(new_pin.encode()).hexdigest()
    conn = sqlite3.connect(str(MASTER_DB_PATH))
    conn.execute("INSERT OR REPLACE INTO master_pins(key,pin_hash) VALUES('__superadmin__',?)", (h,))
    conn.commit()
    conn.close()

