def get_attendance_log(emp_id=None, filter_date=None, limit=300):
    """
    Reads from attendance_log table.
    login_dt / logout_dt are stored when employee saves their timesheet
    with the Login/Logout time pickers filled in.
    """
    conds, params = ["1=1"], []
    if emp_id:
        conds.append("al.emp_id=?"); params.append(emp_id)
    if filter_date:
        fd = filter_date.isoformat() if hasattr(filter_date, "isoformat") else filter_date
        conds.append("al.session_date=?"); params.append(fd)
    params.append(limit)
    where = " AND ".join(conds)
    sql = """
        SELECT
            al.emp_id,
            e.full_name,
            e.role,
            al.session_date                         AS login_date,
            SUBSTR(al.login_dt,  12, 5)             AS login_time,
            SUBSTR(al.logout_dt, 12, 5)             AS logout_time,
            al.duration_mins,
            CASE WHEN al.duration_mins IS NOT NULL
                 THEN CAST(CAST(al.duration_mins/60 AS INT) AS TEXT) || 'h ' ||
                      CAST(CAST(al.duration_mins - CAST(al.duration_mins/60 AS INT)*60 AS INT) AS TEXT) || 'm'
                 ELSE '—' END                       AS duration_fmt
        FROM attendance_log al
        LEFT JOIN employees e ON al.emp_id = e.emp_id
        WHERE """ + where + """
        ORDER BY al.id DESC
        LIMIT ?"""
    with get_conn() as conn:
        rows = conn.execute(sql, params).fetchall()
        return [dict(r) for r in rows]

