SESSION_TIMEOUT_MINS = 60

# ── Per-request branch DB switching ───────────────────────────────────────────
@app.before_request
def _set_branch_db():
    """Switch _jaa.DB_PATH to the branch stored in session — called on every request."""
    if request.endpoint == "static":
        return
    branch = session.get("branch")
    if branch and branch in BRANCHES:
        # This sets both thread-local AND _jaa.DB_PATH atomically for this request
        switch_branch_db(branch)
    elif session.get("emp_id") or session.get("role") in ("admin", "partner", "superadmin"):
        # Stale session without branch — force re-login
        session.clear()
        return redirect(url_for("login"))

# ── Decorators ────────────────────────────────────────────────────────────────
def _check_timeout():
    last = session.get("last_active")
    if last:
        idle = (datetime.now() - datetime.fromisoformat(last)).total_seconds() / 60
        if idle > SESSION_TIMEOUT_MINS:
            session.clear()
            return True
    session["last_active"] = datetime.now().isoformat()
    return False

def login_required(f):
    @wraps(f)
    def d(*a, **kw):
        if not session.get("emp_id") and session.get("role") not in ("admin", "partner"):
            return redirect(url_for("login"))
        if _check_timeout():
            return redirect(url_for("login", timeout=1))
        return f(*a, **kw)
    return d

def admin_required(f):
    """Allows both admin and partner — blocks billing for admin via partner_only."""
    @wraps(f)
    def d(*a, **kw):
        if session.get("role") not in ("admin", "partner"):
            return redirect(url_for("login"))
        if _check_timeout():
            return redirect(url_for("login", timeout=1))
        return f(*a, **kw)
    return d

def partner_required(f):
    """Partner-only routes — admin gets Access Denied."""
    @wraps(f)
    def d(*a, **kw):
        role = session.get("role")
        if role not in ("admin", "partner"):
            return redirect(url_for("login"))
        if _check_timeout():
            return redirect(url_for("login", timeout=1))
        if role == "admin":
            return render_template("access_denied.html")
        return f(*a, **kw)
    return d

def billing_advice_required(f):
    """Password-locked route for Billing Advice.
    Only partners who pass the billing_advice_pin check can access it.
    """
    @wraps(f)
    def _d(*a, **kw):
        role = session.get("role")
        if role not in ("admin", "partner"):
            return redirect(url_for("login"))
        if _check_timeout():
            return redirect(url_for("login", timeout=1))
        if role != "partner":
            return render_template("access_denied.html")
        # Check if this session has already unlocked billing advice
        if not session.get("billing_advice_unlocked"):
            return redirect(url_for("billing_advice_unlock"))
        return f(*a, **kw)
    return _d

def superadmin_required(f):
    @wraps(f)
    def d(*a, **kw):
        if not session.get("superadmin"):
            return redirect(url_for("superadmin_login"))
        if _check_timeout():
            return redirect(url_for("superadmin_login", timeout=1))
        return f(*a, **kw)
    return d

