@app.route("/login", methods=["GET", "POST"])
def login():
    if not DB_READY:
        return render_template("error.html",
            msg=f"JAA_Timesheet_v17.py not found in: {BASE_DIR.parent}<br>{_import_error}")
    error   = None
    timeout = request.args.get("timeout")
    if request.method == "POST":
        branch  = request.form.get("branch", "").strip()
        role    = request.form.get("role", "user")
        # Each tab has its own named input to avoid collisions
        if role == "partner":
            pin = request.form.get("partner_pin", "").strip()
        elif role == "admin":
            pin = request.form.get("pin", "").strip()
        else:
            pin = request.form.get("emp_pin", "").strip()
        if branch not in BRANCHES:
            error = "Please select a branch."
        else:
            # Switch DB to selected branch before any DB calls
            switch_branch_db(branch)
            # Ensure this branch DB is initialised
            try:
                init_db()
                import sqlite3 as _sq2
                _lc = _sq2.connect(str(_jaa.DB_PATH))
                _lc_emp = [r[1] for r in _lc.execute("PRAGMA table_info(employees)").fetchall()]
                _lc_att = [r[1] for r in _lc.execute("PRAGMA table_info(attendance_log)").fetchall()]
                if "date_of_birth" not in _lc_emp:
                    _lc.execute("ALTER TABLE employees ADD COLUMN date_of_birth TEXT")
                if "gstin" not in _lc_emp:
                    _lc.execute("ALTER TABLE employees ADD COLUMN gstin TEXT DEFAULT ''")
                if "session_date" not in _lc_att:
                    _lc.execute("ALTER TABLE attendance_log ADD COLUMN session_date TEXT")
                _lc.commit(); _lc.close()
                _migrate_billing()
                if hasattr(_jaa, "seed_learning_categories"):
                    _jaa.seed_learning_categories()
                if hasattr(_jaa, "seed_work_mapping"):
                    _jaa.seed_work_mapping(overwrite=True)
                seed_birthdays()
            except Exception as _ie:
                print(f"Branch init warning: {_ie}")
            if role == "partner":
                # switch_branch_db already called above — use _jaa directly
                # Partners log in via their own emp_id + personal PIN
                partner_name = request.form.get("partner_name", "").strip()
                emp_p = get_employee_by_name(partner_name)
                if not emp_p:
                    error = "Partner employee not found."
                elif emp_p.get("role", "").lower() != "partner":
                    error = "Selected employee is not a Partner."
                elif emp_p["status"] != "Active":
                    error = f"Account is {emp_p['status']}. Contact Admin."
                elif not _jaa.verify_pin(emp_p["emp_id"], pin):
                    error = "Incorrect partner PIN."
                else:
                    session.clear()
                    session["role"]         = "partner"
                    session["emp_id"]       = emp_p["emp_id"]
                    session["emp_name"]     = emp_p["full_name"]
                    session["name"]         = emp_p["full_name"]
                    session["branch"]       = branch
                    session["branch_label"] = BRANCHES[branch]
                    session["last_active"]  = datetime.now().isoformat()
                    _check_intern_lifecycle()
                    return redirect(url_for("admin_dashboard"))
            elif role == "admin":
                if _jaa.verify_pin("__admin__", pin):
                    session.clear()
                    session["role"]   = "admin"
                    session["name"]   = "Admin"
                    session["branch"] = branch
                    session["branch_label"] = BRANCHES[branch]
                    session["last_active"]  = datetime.now().isoformat()
                    _check_intern_lifecycle()
                    return redirect(url_for("admin_dashboard"))
                error = "Incorrect admin PIN."
            else:
                name    = request.form.get("name", "").strip()
                pin_emp = request.form.get("emp_pin", "").strip() or pin
                emp     = get_employee_by_name(name)
                if not emp:                                    error = "Employee not found."
                elif emp["status"] != "Active":                error = f"Account is {emp['status']}. Contact Admin."
                elif not verify_pin(emp["emp_id"], pin_emp):   error = "Incorrect PIN."
                else:
                    session.clear()
                    session["emp_id"]       = emp["emp_id"]
                    session["emp_name"]     = emp["full_name"]
                    session["role"]         = "user"
                    session["emp_role"]     = emp.get("role", "Employee")
                    session["branch"]       = branch
                    session["branch_label"] = BRANCHES[branch]
                    session["last_active"]  = datetime.now().isoformat()
                    # DO NOT call record_login here — it inserts a new row every login
                    # Attendance is captured only via the Check In button (8AM+)
                    return redirect(url_for("timesheet"))
    # For GET: load employees list only if branch already in session
    employees = []
    pre_branch = request.args.get("branch", "")
    if pre_branch in BRANCHES:
        switch_branch_db(pre_branch)
        try: employees = get_all_employees()
        except Exception: employees = []
    return render_template("login.html",
        employees=employees,
        error=error,
        timeout=timeout,
        branches=BRANCHES,
        pre_branch=pre_branch)

@app.route("/api/branch-employees")
def api_branch_employees():
    """Return employee names for a given branch (for the login dropdown)."""
    branch = request.args.get("branch", "")
    if branch not in BRANCHES:
        return jsonify({"error": "invalid branch", "employees": []})
    switch_branch_db(branch)
    try:
        # Ensure the DB exists and is initialised before querying
        import JAA_Timesheet_v17 as _m
        _m.init_db()
    except Exception:
        pass
    try:
        import JAA_Timesheet_v17 as _m
        import sqlite3
        conn = sqlite3.connect(str(_m.DB_PATH), timeout=10)
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            "SELECT full_name, role FROM employees WHERE status='Active' ORDER BY full_name"
        ).fetchall()
        conn.close()
        return jsonify([{"full_name": r["full_name"], "role": r["role"]} for r in rows])
    except Exception as ex:
        return jsonify({"error": str(ex), "employees": []})

