@app.route("/admin/cleanup-attendance")
@admin_required
def admin_cleanup_attendance():
    """Delete duplicate attendance rows — keep only earliest per emp per date."""
    try:
        with _jaa.get_conn() as conn:
            # Find all duplicates — keep lowest id per emp+date
            dupes = conn.execute("""
                SELECT id FROM attendance_log
                WHERE id NOT IN (
                    SELECT MIN(id) FROM attendance_log
                    GROUP BY emp_id, session_date
                )
            """).fetchall()
            count = len(dupes)
            if count:
                conn.execute("""
                    DELETE FROM attendance_log
                    WHERE id NOT IN (
                        SELECT MIN(id) FROM attendance_log
                        GROUP BY emp_id, session_date
                    )
                """)
        return jsonify({"ok": True, "deleted_duplicates": count,
                        "message": f"Cleaned up {count} duplicate rows."})
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)})

