# ── Employee — Timesheet ──────────────────────────────────────────────────────
@app.route("/timesheet")
@login_required
def timesheet():
    emp   = cur_emp()
    today = date.today()
    on_leave, leave_reason = is_on_leave(emp["emp_id"], today)
    locked  = is_timesheet_locked(str(today), role="user")
    entries = load_entries(emp_id=emp["emp_id"], filter_date=today)
    total   = sum(float(e.get("total_hrs") or 0) for e in entries)
    recent  = []
    for i in range(1, GRACE_DAYS + 1):
        d  = today - timedelta(days=i)
        de = load_entries(emp_id=emp["emp_id"], filter_date=d)
        recent.append({
            "date": str(d), "display": d.strftime("%d %b"),
            "day_name": d.strftime("%A"),
            "entries": de,
            "locked": is_timesheet_locked(str(d), role="user"),
            "total_hrs": sum(float(e.get("total_hrs") or 0) for e in de),
        })
    # Fetch today's check-in/out status
    checkin_info = {"checked_in": False, "checked_out": False,
                    "login_time": "", "logout_time": "", "duration": ""}
    try:
        with get_conn() as conn:
            row = conn.execute(
                "SELECT login_dt, logout_dt, duration_mins FROM attendance_log "
                "WHERE emp_id=? AND session_date=? ORDER BY id ASC LIMIT 1",
                (emp["emp_id"], str(today))
            ).fetchone()
        if row:
            checkin_info["checked_in"]  = bool(row["login_dt"])
            checkin_info["checked_out"] = bool(row["logout_dt"])
            if row["login_dt"]:
                checkin_info["login_time"] = row["login_dt"][11:16]   # HH:MM
            if row["logout_dt"]:
                checkin_info["logout_time"] = row["logout_dt"][11:16]
            if row["duration_mins"]:
                dm = int(row["duration_mins"])
                checkin_info["duration"] = f"{dm//60}h {dm%60}m"
    except Exception:
        pass
    # Seed and fetch work mapping — re-assert branch DB before each call
    branch = session.get("branch")
    if branch and branch in BRANCHES:
        switch_branch_db(branch)   # re-assert just before DB calls
    try:
        _jaa.seed_work_mapping()
    except Exception as _se:
        print(f"[timesheet] seed_work_mapping error: {_se}")
    try:
        all_categories = _jaa.get_work_categories()
        full_mapping   = _jaa.get_full_mapping()
        all_companies  = _jaa.get_all_companies()
        # Filter companies by assignment if the employee has assignments
        is_restricted  = False
        if get_employee_assigned_companies and emp:
            assigned = get_employee_assigned_companies(emp["emp_id"])
            if assigned:
                all_companies = assigned
                is_restricted = True
        print(f"[timesheet] branch={branch} cats={len(all_categories)} mapping={len(full_mapping)} cos={len(all_companies)}")
    except Exception as _fe:
        print(f"[timesheet] fetch error: {_fe}")
        import traceback; traceback.print_exc()
        all_categories = []
        full_mapping   = {}
        all_companies  = []
        is_restricted  = False
    return render_template("timesheet.html",
        emp=emp, today=today, on_leave=on_leave,
        leave_reason=leave_reason, locked=locked,
        entries=entries, total_hrs=total, recent=recent,
        companies=all_companies,
        is_restricted=is_restricted,
        categories=all_categories,
        full_mapping=full_mapping,
        reporting_opts=REPORTING_OPT,
        work_locations=WORK_LOCATION,
        statuses=STATUSES,
        daily_target=DAILY_TARGET,
        lock_day=LOCK_DAY, grace_days=GRACE_DAYS,
        session_timeout_mins=SESSION_TIMEOUT_MINS,
        checkin_info=checkin_info,
        task_summary=_build_task_summary(emp["emp_id"]),
        notif_unread=(_jaa.get_unread_count(emp["emp_id"]) if get_unread_count else 0),
        now=datetime.now())

@app.route("/api/checkin", methods=["POST"])
@login_required
def api_checkin():
    """Record Check In — only allowed from 8:00 AM. One row per employee per day, never duplicated."""
    emp   = cur_emp()
    today = date.today()
    now   = datetime.now()

    # Block check-in before 8:00 AM
    if now.hour < 8:
        return jsonify({"ok": False, "error": "Check In is only available from 8:00 AM onwards."})

    try:
        with _jaa.get_conn() as conn:
            # Get the EARLIEST record for today (in case duplicates exist from before)
            existing = conn.execute(
                "SELECT id, login_dt FROM attendance_log "
                "WHERE emp_id=? AND session_date=? ORDER BY id ASC LIMIT 1",
                (emp["emp_id"], str(today))
            ).fetchone()

            # Already has a check-in — return the original locked time, never touch it
            if existing and existing["login_dt"]:
                t = datetime.fromisoformat(existing["login_dt"])
                return jsonify({"ok": True, "already": True,
                                "login_time":      t.strftime("%H:%M"),
                                "login_time_full": t.strftime("%I:%M %p")})

            # No row at all — insert exactly one row
            if not existing:
                conn.execute(
                    "INSERT INTO attendance_log (emp_id, login_dt, session_date) VALUES (?,?,?)",
                    (emp["emp_id"], now.isoformat(), str(today))
                )
            else:
                # Row exists but no login_dt yet — update it
                conn.execute(
                    "UPDATE attendance_log SET login_dt=? WHERE id=?",
                    (now.isoformat(), existing["id"])
                )

        return jsonify({"ok": True, "already": False,
                        "login_time":      now.strftime("%H:%M"),
                        "login_time_full": now.strftime("%I:%M %p")})
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)})


@app.route("/api/checkout", methods=["POST"])
@login_required
def api_checkout():
    """Record Check Out, then save + submit timesheet entries atomically."""
    emp   = cur_emp()
    today = date.today()
    now   = datetime.now()
    data  = request.get_json() or {}

    if is_timesheet_locked(str(today), role="user"):
        return jsonify({"ok": False, "error": "Timesheet is locked for today."})

    # 1. Verify check-in exists — always use earliest row for today
    try:
        with _jaa.get_conn() as conn:
            row = conn.execute(
                "SELECT id, login_dt FROM attendance_log "
                "WHERE emp_id=? AND session_date=? ORDER BY id ASC LIMIT 1",
                (emp["emp_id"], str(today))
            ).fetchone()
        if not row or not row["login_dt"]:
            return jsonify({"ok": False, "error": "Please Check In first."})
        existing_id  = row["id"]
        login_dt_str = row["login_dt"]
    except Exception as ex:
        return jsonify({"ok": False, "error": f"DB error: {ex}"})

    # 2. Save timesheet entries
    rows = []
    for e in data.get("entries", []):
        if not e.get("work_category"): continue
        try:
            st  = e.get("start_time", "") or ""
            et  = e.get("end_time",   "") or ""
            brk = int(e.get("break_mins", 0) or 0)
            if st and et:
                s   = datetime.strptime(st, "%H:%M")
                en  = datetime.strptime(et, "%H:%M")
                hrs = round(max((en - s).seconds / 3600 - brk / 60, 0), 2)
            else:
                hrs = 0
        except Exception:
            hrs = 0
        rows.append({"date": str(today), "day": today.strftime("%A"),
            "emp_id": emp["emp_id"], "reporting_to": data.get("reporting_to", ""),
            "company_code": e.get("company_code", ""), "client": e.get("client_name", ""),
            "work_category": e["work_category"], "operational_area": e.get("operational_area", ""),
            "sub_category": e.get("sub_category", ""), "start_time": e.get("start_time", ""),
            "end_time": e.get("end_time", ""), "break_mins": brk, "total_hrs": hrs,
            "task_desc": e.get("task_desc", ""), "notes": e.get("notes", ""),
            "work_location": e.get("work_location", ""), "status": e.get("status", "Completed")})

    if not rows:
        return jsonify({"ok": False, "error": "No valid task entries to save. Please fill in at least one row."})

    ok, err = _branch_call(_jaa.save_timesheet_entries, rows)
    if not ok:
        return jsonify({"ok": False, "error": err or "Failed to save entries."})

    try:
        _branch_call(_jaa.upsert_submission, emp["emp_id"], str(today),
                     len(rows), sum(r["total_hrs"] for r in rows))
    except Exception:
        pass

    # 3. Write checkout time + compute duration
    try:
        login_dt  = datetime.fromisoformat(login_dt_str)
        dur_mins  = round(max((now - login_dt).total_seconds() / 60, 0), 1)
        with _jaa.get_conn() as conn:
            conn.execute(
                "UPDATE attendance_log SET logout_dt=?, duration_mins=? WHERE id=?",
                (now.isoformat(), dur_mins, existing_id)
            )
        h = int(dur_mins) // 60; m = int(dur_mins) % 60
        duration_fmt = f"{h}h {m}m"
    except Exception as ex:
        duration_fmt = "—"
        print(f"[checkout] duration error: {ex}")

    return jsonify({"ok": True,
                    "logout_time": now.strftime("%H:%M"),
                    "logout_time_full": now.strftime("%I:%M %p"),
                    "duration": duration_fmt,
                    "entries_saved": len(rows)})


@app.route("/api/save-entries", methods=["POST"])
@login_required
def api_save_entries():
  try:
    emp  = cur_emp(); data = request.get_json() or {}; today = date.today()
    if is_timesheet_locked(str(today), role="user"):
        return jsonify({"ok": False, "error": "Timesheet locked."})
    rows = []
    for e in data.get("entries", []):
        if not e.get("work_category"): continue
        try:
            st  = e.get("start_time", "") or ""
            et  = e.get("end_time",   "") or ""
            brk = int(e.get("break_mins", 0) or 0)
            if st and et:
                s   = datetime.strptime(st, "%H:%M")
                en  = datetime.strptime(et, "%H:%M")
                hrs = round(max((en - s).seconds / 3600 - brk / 60, 0), 2)
            else:
                hrs = 0
        except Exception:
            hrs = 0
        rows.append({"date": str(today), "day": today.strftime("%A"),
            "emp_id": emp["emp_id"], "reporting_to": data.get("reporting_to", ""),
            "company_code": e.get("company_code", ""), "client": e.get("client_name", ""),
            "work_category": e["work_category"], "operational_area": e.get("operational_area", ""),
            "sub_category": e.get("sub_category", ""), "start_time": e.get("start_time", ""),
            "end_time": e.get("end_time", ""), "break_mins": brk, "total_hrs": hrs,
            "task_desc": e.get("task_desc", ""), "notes": e.get("notes", ""),
            "work_location": e.get("work_location", ""), "status": e.get("status", "Completed")})
    if not rows: return jsonify({"ok": False, "error": "No valid entries."})
    ok, err = save_timesheet_entries(rows)
    if ok:
        upsert_submission(emp["emp_id"], str(today), len(rows), sum(r["total_hrs"] for r in rows))
        # Write login/logout to attendance_log from the time pickers
        try:
            login_t  = data.get("login_time", "").strip()
            logout_t = data.get("logout_time", "").strip()
            if login_t and logout_t:
                login_dt  = datetime.strptime(f"{today} {login_t}",  "%Y-%m-%d %H:%M")
                logout_dt = datetime.strptime(f"{today} {logout_t}", "%Y-%m-%d %H:%M")
                dur_mins  = round(max((logout_dt - login_dt).total_seconds() / 60, 0), 1)
                with get_conn() as conn:
                    conn.execute(
                        "DELETE FROM attendance_log WHERE emp_id=? AND session_date=?",
                        (emp["emp_id"], str(today))
                    )
                    conn.execute(
                        "INSERT INTO attendance_log (emp_id, login_dt, logout_dt, duration_mins, session_date) VALUES (?,?,?,?,?)",
                        (emp["emp_id"], login_dt.isoformat(), logout_dt.isoformat(), dur_mins, str(today))
                    )
        except Exception:
            pass  # Don't block timesheet save if attendance write fails
    return jsonify({"ok": ok, "error": err})
  except Exception as ex:
    return jsonify({"ok": False, "error": f"Server error: {str(ex)}"})

