@app.route("/api/edit-entry", methods=["POST"])
@login_required
def api_edit_entry():
    data     = request.get_json()
    entry_id = data.get("id")
    d        = date.fromisoformat(data["entry_date"])
    role     = session.get("role", "user")
    if is_timesheet_locked(str(d), role=role):
        return jsonify({"ok": False, "error": "Locked."})
    try:
        s   = datetime.strptime(data["start_time"], "%H:%M")
        en  = datetime.strptime(data["end_time"],   "%H:%M")
        brk = int(data.get("break_mins", 0) or 0)
        hrs = round(max((en - s).seconds / 3600 - brk / 60, 0), 2)
    except: hrs = float(data.get("total_hrs", 0))
    ok = update_timesheet_entry(entry_id,
        work_category=data.get("work_category", ""),
        operational_area=data.get("operational_area", ""),
        sub_category=data.get("sub_category", ""),
        start_time=data.get("start_time", ""),
        end_time=data.get("end_time", ""),
        break_mins=brk, total_hrs=hrs,
        task_desc=data.get("task_desc", ""),
        work_location=data.get("work_location", ""),
        status=data.get("status", "Completed"),
        notes=data.get("notes", ""))
    return jsonify({"ok": bool(ok)})

