def make_xlsx_response(headers, rows, sheet_title, filename):
    """Build a styled Excel file and return a Flask response."""
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = sheet_title

    # Styles
    hdr_font    = Font(name="Calibri", bold=True, color="FFFFFF", size=11)
    hdr_fill    = PatternFill("solid", fgColor="0D2137")          # JAA navy
    alt_fill    = PatternFill("solid", fgColor="EFF6FF")          # light blue
    border_side = Side(style="thin", color="CCCCCC")
    cell_border = Border(left=border_side, right=border_side,
                         top=border_side,  bottom=border_side)
    center_aln  = Alignment(horizontal="center", vertical="center", wrap_text=True)
    left_aln    = Alignment(horizontal="left",   vertical="center", wrap_text=True)

    # Header row
    ws.row_dimensions[1].height = 22
    for col_idx, h in enumerate(headers, 1):
        cell = ws.cell(row=1, column=col_idx, value=h)
        cell.font      = hdr_font
        cell.fill      = hdr_fill
        cell.alignment = center_aln
        cell.border    = cell_border

    # Data rows
    for row_idx, row in enumerate(rows, 2):
        fill = alt_fill if row_idx % 2 == 0 else None
        ws.row_dimensions[row_idx].height = 18
        for col_idx, val in enumerate(row, 1):
            cell = ws.cell(row=row_idx, column=col_idx, value=val)
            if fill: cell.fill = fill
            cell.border    = cell_border
            cell.alignment = left_aln if col_idx <= 3 else center_aln

    # Auto-fit column widths
    for col_idx, _ in enumerate(headers, 1):
        col_letter = get_column_letter(col_idx)
        max_len = max(
            (len(str(ws.cell(row=r, column=col_idx).value or "")) for r in range(1, ws.max_row + 1)),
            default=8
        )
        ws.column_dimensions[col_letter].width = min(max_len + 4, 40)

    # Freeze header row
    ws.freeze_panes = "A2"

    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    resp = make_response(buf.read())
    resp.headers["Content-Type"]        = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    resp.headers["Content-Disposition"] = f"attachment; filename={filename}"
    return resp

