# ── Admin — Reports ───────────────────────────────────────────────────────────
@app.route("/admin/reports")
@admin_required
def admin_reports():
  try:
    today         = date.today()
    start         = request.args.get("start", today.replace(day=1).isoformat())
    end           = request.args.get("end",   today.isoformat())
    productivity  = get_employee_productivity(start, end) or []
    client_effort = get_client_effort(start, end) or []

    with get_conn() as conn:
        # Work Category breakdown
        cat_report = [dict(r) for r in conn.execute("""
            SELECT work_category, COUNT(*) AS entry_count,
                   ROUND(SUM(total_hrs),2) AS total_hrs,
                   COUNT(DISTINCT emp_id) AS emp_count
            FROM timesheet_entries
            WHERE entry_date BETWEEN ? AND ?
              AND work_category != ''
            GROUP BY work_category ORDER BY total_hrs DESC
        """, (start, end)).fetchall()]

        # Daily submission tracker
        daily_sub = [dict(r) for r in conn.execute("""
            SELECT entry_date, COUNT(DISTINCT emp_id) AS submitted,
                   ROUND(SUM(total_hrs),2) AS total_hrs
            FROM timesheet_entries
            WHERE entry_date BETWEEN ? AND ?
            GROUP BY entry_date ORDER BY entry_date DESC
        """, (start, end)).fetchall()]

        # Work location breakdown
        location_report = [dict(r) for r in conn.execute("""
            SELECT work_location, COUNT(*) AS entry_count,
                   ROUND(SUM(total_hrs),2) AS total_hrs,
                   COUNT(DISTINCT emp_id) AS emp_count
            FROM timesheet_entries
            WHERE entry_date BETWEEN ? AND ?
              AND work_location != ''
            GROUP BY work_location ORDER BY total_hrs DESC
        """, (start, end)).fetchall()]

        # Leave summary — find the actual leaves table name
        leave_tables = [r[0] for r in conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name LIKE '%leave%'"
        ).fetchall()]
        leave_table = leave_tables[0] if leave_tables else None
        if leave_table:
            # detect date column name
            leave_cols = [r[1] for r in conn.execute(f"PRAGMA table_info({leave_table})").fetchall()]
            date_col = next((c for c in leave_cols if 'date' in c.lower()), None)
            if date_col:
                leave_summary = [dict(r) for r in conn.execute(f"""
                    SELECT e.full_name, e.role,
                           COUNT(l.id) AS leave_days,
                           SUM(CASE WHEN l.status='Approved' THEN 1 ELSE 0 END) AS approved,
                           SUM(CASE WHEN l.status='Pending'  THEN 1 ELSE 0 END) AS pending
                    FROM {leave_table} l
                    JOIN employees e ON l.emp_id = e.emp_id
                    WHERE l.{date_col} BETWEEN ? AND ?
                    GROUP BY l.emp_id ORDER BY leave_days DESC
                """, (start, end)).fetchall()]
            else:
                leave_summary = []
        else:
            leave_summary = []

        # Total active employees in period
        total_emps = conn.execute(
            "SELECT COUNT(DISTINCT emp_id) FROM timesheet_entries WHERE entry_date BETWEEN ? AND ?",
            (start, end)
        ).fetchone()[0]

    total_hrs    = round(sum(float(r.get("total_hrs") or 0) for r in productivity), 1)
    total_leaves = sum(int(r.get("leave_days") or 0) for r in leave_summary)
    total_clients = len(client_effort)

    return render_template("admin_reports.html",
        productivity=productivity, client_effort=client_effort,
        cat_report=cat_report, daily_sub=daily_sub,
        location_report=location_report, leave_summary=leave_summary,
        total_emps=total_emps, total_hrs=total_hrs,
        total_leaves=total_leaves, total_clients=total_clients,
        start=start, end=end, daily_target=DAILY_TARGET)
  except Exception as ex:
    import traceback; traceback.print_exc()
    return f"<h2>Reports Error</h2><pre>{traceback.format_exc()}</pre>", 500

@app.route("/admin/reports/export")
@admin_required
def admin_reports_export():
    today = date.today()
    start = request.args.get("start", today.replace(day=1).isoformat())
    end   = request.args.get("end",   today.isoformat())

    productivity  = get_employee_productivity(start, end)
    client_effort = get_client_effort(start, end)

    with get_conn() as conn:
        cat_report = [dict(r) for r in conn.execute("""
            SELECT work_category, COUNT(*) AS entry_count,
                   ROUND(SUM(total_hrs),2) AS total_hrs,
                   COUNT(DISTINCT emp_id) AS emp_count
            FROM timesheet_entries WHERE entry_date BETWEEN ? AND ?
              AND work_category != ''
            GROUP BY work_category ORDER BY total_hrs DESC
        """, (start, end)).fetchall()]

        location_report = [dict(r) for r in conn.execute("""
            SELECT work_location, COUNT(*) AS entry_count,
                   ROUND(SUM(total_hrs),2) AS total_hrs,
                   COUNT(DISTINCT emp_id) AS emp_count
            FROM timesheet_entries WHERE entry_date BETWEEN ? AND ?
              AND work_location != ''
            GROUP BY work_location ORDER BY total_hrs DESC
        """, (start, end)).fetchall()]

        leave_tables = [r[0] for r in conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name LIKE '%leave%'"
        ).fetchall()]
        leave_table = leave_tables[0] if leave_tables else None
        if leave_table:
            leave_cols = [r[1] for r in conn.execute(f"PRAGMA table_info({leave_table})").fetchall()]
            date_col = next((c for c in leave_cols if 'date' in c.lower()), None)
            if date_col:
                leave_summary = [dict(r) for r in conn.execute(f"""
                    SELECT e.full_name, e.role,
                           COUNT(l.id) AS leave_days,
                           SUM(CASE WHEN l.status='Approved' THEN 1 ELSE 0 END) AS approved,
                           SUM(CASE WHEN l.status='Pending'  THEN 1 ELSE 0 END) AS pending
                    FROM {leave_table} l JOIN employees e ON l.emp_id = e.emp_id
                    WHERE l.{date_col} BETWEEN ? AND ?
                    GROUP BY l.emp_id ORDER BY leave_days DESC
                """, (start, end)).fetchall()]
            else:
                leave_summary = []
        else:
            leave_summary = []

        daily_sub = [dict(r) for r in conn.execute("""
            SELECT entry_date, COUNT(DISTINCT emp_id) AS submitted,
                   ROUND(SUM(total_hrs),2) AS total_hrs
            FROM timesheet_entries WHERE entry_date BETWEEN ? AND ?
            GROUP BY entry_date ORDER BY entry_date DESC
        """, (start, end)).fetchall()]

    # Build multi-sheet workbook
    hdr_font  = Font(name="Calibri", bold=True, color="FFFFFF", size=11)
    hdr_fill  = PatternFill("solid", fgColor="0D2137")
    alt_fill  = PatternFill("solid", fgColor="EFF6FF")
    bside     = Side(style="thin", color="CCCCCC")
    cborder   = Border(left=bside, right=bside, top=bside, bottom=bside)
    c_aln     = Alignment(horizontal="center", vertical="center", wrap_text=True)
    l_aln     = Alignment(horizontal="left",   vertical="center", wrap_text=True)

    def write_sheet(wb, title, headers, rows):
        ws = wb.create_sheet(title)
        ws.freeze_panes = "A2"
        ws.row_dimensions[1].height = 22
        for ci, h in enumerate(headers, 1):
            c = ws.cell(row=1, column=ci, value=h)
            c.font = hdr_font; c.fill = hdr_fill; c.alignment = c_aln; c.border = cborder
        for ri, row in enumerate(rows, 2):
            fill = alt_fill if ri % 2 == 0 else None
            ws.row_dimensions[ri].height = 17
            for ci, val in enumerate(row, 1):
                c = ws.cell(row=ri, column=ci, value=val)
                if fill: c.fill = fill
                c.border = cborder
                c.alignment = l_aln if ci == 1 else c_aln
        for ci in range(1, len(headers)+1):
            col = get_column_letter(ci)
            mx = max((len(str(ws.cell(row=r, column=ci).value or "")) for r in range(1, ws.max_row+1)), default=8)
            ws.column_dimensions[col].width = min(mx + 4, 42)

    wb = openpyxl.Workbook()
    wb.remove(wb.active)  # remove default sheet

    # Sheet 1 — Productivity
    prod_rows = []
    for r in productivity:
        days = int(r.get("days_worked") or r.get("working_days") or 1)
        hrs  = float(r.get("total_hrs") or 0)
        avg  = round(hrs / max(days, 1), 2)
        prod_rows.append([r.get("full_name",""), r.get("role",""), days,
                          round(hrs,2), avg, "Yes" if avg >= DAILY_TARGET else "No"])
    write_sheet(wb, "Productivity", ["Employee","Role","Days Worked","Total Hrs","Avg Hrs/Day","Target Met"], prod_rows)

    # Sheet 2 — Client Effort
    write_sheet(wb, "Client Effort",
        ["Client","Entries","Total Hrs"],
        [[r.get("client_name","—"), r.get("entry_count",0), round(float(r.get("total_hrs",0)),2)] for r in client_effort])

    # Sheet 3 — Work Category
    write_sheet(wb, "Work Categories",
        ["Work Category","Entries","Total Hrs","Employees"],
        [[r["work_category"], r["entry_count"], r["total_hrs"], r["emp_count"]] for r in cat_report])

    # Sheet 4 — Work Location
    write_sheet(wb, "Work Locations",
        ["Location","Entries","Total Hrs","Employees"],
        [[r["work_location"], r["entry_count"], r["total_hrs"], r["emp_count"]] for r in location_report])

    # Sheet 5 — Leave Summary
    write_sheet(wb, "Leave Summary",
        ["Employee","Role","Total Leave Days","Approved","Pending"],
        [[r["full_name"], r["role"], r["leave_days"], r["approved"], r["pending"]] for r in leave_summary])

    # Sheet 6 — Daily Submissions
    write_sheet(wb, "Daily Submissions",
        ["Date","Employees Submitted","Total Hrs"],
        [[r["entry_date"], r["submitted"], r["total_hrs"]] for r in daily_sub])

    buf = io.BytesIO()
    wb.save(buf); buf.seek(0)
    resp = make_response(buf.read())
    resp.headers["Content-Type"]        = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    resp.headers["Content-Disposition"] = f"attachment; filename=jaa_full_report_{start}_to_{end}.xlsx"
    return resp

