@app.route("/api/company/update", methods=["POST"])
@admin_required
def api_company_update():
    d           = request.get_json()
    old_code    = d.get("unique_code", "").strip()
    new_code    = d.get("new_unique_code", "").strip() or old_code
    short_code  = d.get("short_code", "").strip()
    full_name   = d.get("full_name", "").strip()
    if not old_code:
        return jsonify({"ok": False, "error": "Missing code"})
    try:
        with get_conn() as conn:
            conn.execute("PRAGMA foreign_keys = OFF")
            if new_code != old_code:
                exists = conn.execute(
                    "SELECT 1 FROM companies WHERE unique_code=? AND unique_code!=?",
                    (new_code, old_code)
                ).fetchone()
                if exists:
                    conn.execute("PRAGMA foreign_keys = ON")
                    return jsonify({"ok": False, "error": "Code already exists"})
            conn.execute(
                "UPDATE companies SET unique_code=?, short_code=?, full_name=? WHERE unique_code=?",
                (new_code, short_code, full_name, old_code)
            )
            if new_code != old_code:
                conn.execute(
                    "UPDATE timesheet_entries SET company_code=? WHERE company_code=?",
                    (new_code, old_code)
                )
            conn.execute("PRAGMA foreign_keys = ON")
        return jsonify({"ok": True})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)})


@app.route("/api/company/delete", methods=["POST"])
@admin_required
def api_company_delete():
    d    = request.get_json()
    code = d.get("unique_code", "").strip()
    if not code:
        return jsonify({"ok": False, "error": "Missing code"})
    try:
        with get_conn() as conn:
            conn.execute("PRAGMA foreign_keys = OFF")
            # Null out the company_code in timesheet entries (keep history)
            conn.execute(
                "UPDATE timesheet_entries SET company_code=NULL, client='' WHERE company_code=?",
                (code,)
            )
            conn.execute("DELETE FROM companies WHERE unique_code=?", (code,))
            conn.execute("PRAGMA foreign_keys = ON")
        return jsonify({"ok": True})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)})

