@app.route("/admin/attendance/export")
@admin_required
def admin_attendance_export():
    fd_str   = request.args.get("date", "")
    emp_name = request.args.get("emp", "All")
    try: fd = date.fromisoformat(fd_str) if fd_str else None
    except: fd = None
    emp_obj = get_employee_by_name(emp_name) if emp_name != "All" else None
    eid     = emp_obj["emp_id"] if emp_obj else None
    logs    = get_attendance_log(emp_id=eid, filter_date=fd, limit=10000)
    headers = ["Employee","EMP ID","Role","Date","Login Time","Logout Time","Duration","Status"]
