# ── Admin — Settings ──────────────────────────────────────────────────────────
@app.route("/admin/settings", methods=["GET", "POST"])
@admin_required
def admin_settings():
    cfg = load_config(); msg = None
    if request.method == "POST":
        action = request.form.get("action", "")
        if action == "save":
            cfg["cutoff_time"]   = request.form.get("cutoff_time", "20:30")
            cfg["late_cutoff"]   = request.form.get("late_cutoff", "20:00")
            cfg["email_enabled"] = request.form.get("email_enabled") == "on"
            cfg["manager_email"] = request.form.get("manager_email", "")
            cfg["smtp_host"]     = request.form.get("smtp_host", "")
            cfg["smtp_port"]     = int(request.form.get("smtp_port", 587) or 587)
            cfg["smtp_user"]     = request.form.get("smtp_user", "")
            cfg["smtp_pass"]     = request.form.get("smtp_pass", "")
            save_config(cfg); msg = ("success", "Settings saved!")
        elif action == "backup":
            try:
                BACKUP_DIR.mkdir(parents=True, exist_ok=True)
                ts   = datetime.now().strftime("%Y_%m_%d_%H%M%S")
                dest = BACKUP_DIR / f"jaa_manual_backup_{ts}.db"
                shutil.copy2(str(DB_PATH), str(dest))
                msg = ("success", f"Backup saved: {dest.name}")
            except Exception as e:
                msg = ("error", f"Backup failed: {e}")
        elif action == "clear_trial":
            keep_emp = request.form.get("keep_emp") == "on"
            keep_co  = request.form.get("keep_co")  == "on"
            counts   = clear_trial_data(keep_employees=keep_emp, keep_companies=keep_co)
            total    = sum(counts.values())
            msg = ("success", f"Trial data cleared. {total} records removed.")
        elif action == "change_admin_pin":
            old = request.form.get("old_pin", "").strip()
            new = request.form.get("new_pin", "").strip()
            if verify_pin("__admin__", old):
                change_pin("__admin__", new)
                msg = ("success", "Admin PIN changed!")
            else:
                msg = ("error", "Current PIN incorrect.")
        elif action == "test_email":
            if send_email:
                ok, err = send_email(cfg, cfg.get("manager_email", ""),
                                     "JAA Timesheet — Test Email",
                                     "<p>Test email from JAA Timesheet Web App ✅</p>")
                msg = ("success", "Test email sent!") if ok else ("error", f"Email failed: {err}")
            else:
                msg = ("error", "Email function not available.")
    try:
        db_size = f"{DB_PATH.stat().st_size / 1024 / 1024:.2f} MB"
        backups = len(list(BACKUP_DIR.glob("jaa_*backup_*.db")))
    except:
        db_size = "Unknown"; backups = 0
    return render_template("admin_settings.html",
        cfg=cfg, msg=msg, db_size=db_size, backups=backups,
        backup_dir=str(BACKUP_DIR),
        today_date=date.today().isoformat())

