@app.route("/api/documents/upload-t1", methods=["POST"])
@admin_required
def api_upload_t1():
    import tempfile, os
    emp_id = request.form.get("emp_id","").strip()
    f = request.files.get("file")
    if not emp_id or not f:
        return jsonify({"ok": False, "error": "Missing data."})
    # Only allow T1 for Interns
    emp = get_employee(emp_id)
    if not emp or emp.get("role") != "Intern":
        return jsonify({"ok": False, "error": "T1 upload is only allowed for Interns."})
    with tempfile.NamedTemporaryFile(delete=False, suffix=".pdf") as tmp:
        f.save(tmp.name)
        ok, msg = _jaa.upload_t1(emp_id, tmp.name)
    os.unlink(tmp.name) if not ok else None
    return jsonify({"ok": ok, "msg": msg})

@app.route("/api/documents/upload-t5", methods=["POST"])
@admin_required
def api_upload_t5():
    import tempfile, os
    emp_id = request.form.get("emp_id","").strip()
    f = request.files.get("file")
    if not emp_id or not f:
        return jsonify({"ok": False, "error": "Missing data."})
    # Only allow T5 for Interns
    emp = get_employee(emp_id)
    if not emp or emp.get("role") != "Intern":
        return jsonify({"ok": False, "error": "T5 upload is only allowed for Interns."})
    with tempfile.NamedTemporaryFile(delete=False, suffix=".pdf") as tmp:
        f.save(tmp.name)
        ok, msg = _jaa.upload_t5(emp_id, tmp.name)
    os.unlink(tmp.name) if not ok else None
    if ok:
        # Auto-deactivate intern — their tenure is complete
        try:
            with get_conn() as conn:
                conn.execute(
                    "UPDATE employees SET status='Inactive' WHERE emp_id=?",
                    (emp_id,)
                )
        except Exception:
            pass
        msg = f"T5 uploaded. {emp.get('full_name',emp_id)} has been marked Inactive — internship complete."
    return jsonify({"ok": ok, "msg": msg})

