import json as _json
from collections import OrderedDict as _OD

def _migrate_billing():
    if not DB_READY:
        print("  billing: DB not ready yet, skipping migration")
        return
    try:
        with get_conn() as conn:
            # Add gstin column to companies if missing
            cols = [r[1] for r in conn.execute("PRAGMA table_info(companies)").fetchall()]
            if "gstin" not in cols:
                conn.execute("ALTER TABLE companies ADD COLUMN gstin TEXT DEFAULT ''")
                print("\u2713 companies.gstin added")
            # Create billing_drafts table
            conn.execute(
                "CREATE TABLE IF NOT EXISTS billing_drafts ("
                "  id          INTEGER PRIMARY KEY AUTOINCREMENT,"
                "  emp_id      TEXT NOT NULL,"
                "  emp_name    TEXT NOT NULL,"
                "  client_name TEXT NOT NULL DEFAULT '',"
                "  firm        TEXT NOT NULL DEFAULT '',"
                "  fy          TEXT NOT NULL DEFAULT '',"
                "  data        TEXT NOT NULL DEFAULT '{}',"
                "  created_at  TEXT DEFAULT (datetime('now','localtime')),"
                "  updated_at  TEXT DEFAULT (datetime('now','localtime'))"
                ")"
            )
            print("\u2713 billing_drafts table ready")

            # ── New billing_advice table (Prompt 5) ───────────────────────
            conn.execute("""
                CREATE TABLE IF NOT EXISTS billing_advice (
                    id               INTEGER PRIMARY KEY AUTOINCREMENT,
                    emp_id           TEXT NOT NULL,
                    company_code     TEXT NOT NULL,
                    fy               TEXT NOT NULL DEFAULT '',
                    firm_name        TEXT NOT NULL DEFAULT '',
                    service_desc     TEXT DEFAULT '',
                    audit_date       TEXT DEFAULT '',
                    num_items        TEXT DEFAULT '',
                    udin             TEXT DEFAULT '',
                    first_time       TEXT DEFAULT '',
                    xbrl             TEXT DEFAULT '0',
                    partner1         TEXT DEFAULT '',
                    partner2         TEXT DEFAULT '',
                    trainee1         TEXT DEFAULT '',
                    trainee2         TEXT DEFAULT '',
                    trainee3         TEXT DEFAULT '',
                    months_oop       TEXT DEFAULT '',
                    cra2_by          TEXT DEFAULT 'Company',
                    cra4_by          TEXT DEFAULT 'Company',
                    srn_cra2         TEXT DEFAULT '',
                    srn_cra4         TEXT DEFAULT '',
                    cra2_cost        REAL DEFAULT 0,
                    cra4_cost        REAL DEFAULT 0,
                    contact_name     TEXT DEFAULT '',
                    contact_desig    TEXT DEFAULT '',
                    additional_info  TEXT DEFAULT '',
                    submitted_by     TEXT DEFAULT '',
                    status           TEXT DEFAULT 'draft',
                    form_data_json   TEXT DEFAULT '{}',
                    professional_fee REAL DEFAULT 0,
                    partner_oop1     REAL DEFAULT 0,
                    partner_oop2     REAL DEFAULT 0,
                    invoice_no       TEXT DEFAULT '',
                    invoice_date     TEXT DEFAULT '',
                    tax_type         TEXT DEFAULT '',
                    finalized_by     TEXT DEFAULT '',
                    submitted_at     TEXT DEFAULT (datetime('now','localtime')),
                    finalized_at     TEXT DEFAULT NULL,
                    FOREIGN KEY (emp_id)       REFERENCES employees(emp_id),
                    FOREIGN KEY (company_code) REFERENCES companies(unique_code)
                )
            """)
            conn.execute("CREATE INDEX IF NOT EXISTS idx_ba_company ON billing_advice(company_code)")
            conn.execute("CREATE INDEX IF NOT EXISTS idx_ba_emp    ON billing_advice(emp_id)")
            conn.execute("CREATE INDEX IF NOT EXISTS idx_ba_status ON billing_advice(status)")

            conn.execute("""
                CREATE TABLE IF NOT EXISTS billing_advice_oop (
                    id                  INTEGER PRIMARY KEY AUTOINCREMENT,
                    billing_advice_id   INTEGER NOT NULL,
                    emp_id              TEXT DEFAULT '',
                    person_name         TEXT NOT NULL DEFAULT '',
                    role                TEXT DEFAULT '',
                    travel              REAL DEFAULT 0,
                    refreshment         REAL DEFAULT 0,
                    others              REAL DEFAULT 0,
                    total               REAL DEFAULT 0,
                    reimb_ids_json      TEXT DEFAULT '[]',
                    FOREIGN KEY (billing_advice_id) REFERENCES billing_advice(id)
                )
            """)
            conn.execute("CREATE INDEX IF NOT EXISTS idx_baoop_ba ON billing_advice_oop(billing_advice_id)")
            print("\u2713 billing_advice + billing_advice_oop tables ready")
    except Exception as ex:
        import traceback; traceback.print_exc()
        print(f"  billing migration error: {ex}")

try:
    _migrate_billing()
except Exception as _bex:
    print(f"  billing migration outer error: {_bex}")


