@app.route("/api/billing/next-invoice-no")
@billing_advice_required
def api_billing_next_invoice_no():
    """Generate the next invoice number: BRANCH/FYFY/NNNN e.g. MUM/23240001"""
    try:
        branch = session.get("branch", "mumbai")
        fy     = request.args.get("fy", "").strip()   # e.g. "2023-24"

        # Branch prefix map
        branch_prefix = {
            "mumbai": "MUM", "pune": "PUN",
            "indore": "IND", "delhi": "DEL"
        }.get(branch, branch.upper()[:3])

        # Compress FY: "2023-24" -> "2324", "2024-25" -> "2425"
        fy_code = ""
        if fy and "-" in fy:
            parts = fy.split("-")
            if len(parts) == 2:
                fy_code = parts[0][-2:] + parts[1][-2:]   # last 2 of each year
        if not fy_code:
            from datetime import date as _date
            y = _date.today().year
            fy_code = f"{str(y)[-2:]}{str(y+1)[-2:]}"

        prefix = f"{branch_prefix}/{fy_code}"

        # Find highest serial for this prefix in billing_advice table
        try:
            with get_conn() as conn:
                row = conn.execute(
                    "SELECT invoice_no FROM billing_advice "
                    "WHERE invoice_no LIKE ? ORDER BY invoice_no DESC LIMIT 1",
                    (f"{prefix}%",)
                ).fetchone()
            last_serial = 0
            if row and row["invoice_no"]:
                try:
                    last_serial = int(row["invoice_no"].replace(prefix, ""))
                except (ValueError, TypeError):
                    last_serial = 0
        except Exception:
            last_serial = 0

        next_no = f"{prefix}{str(last_serial + 1).zfill(4)}"
        return jsonify({"ok": True, "invoice_no": next_no})
    except Exception as ex:
        import traceback; traceback.print_exc()
        return jsonify({"ok": False, "error": str(ex)})


