BILLING_PIN_KEY = "__billing_advice__"

def _amount_to_words(amount: float) -> str:
    """Convert a rupee amount (float) to Indian-numbering words."""
    ones = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven",
            "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen",
            "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"]
    tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty",
            "Sixty", "Seventy", "Eighty", "Ninety"]

    def _bh(n):
        if n < 20: return ones[n]
        return tens[n // 10] + (" " + ones[n % 10] if n % 10 else "")

    def _bt(n):
        if n < 100: return _bh(n)
        return ones[n // 100] + " Hundred" + (" " + _bh(n % 100) if n % 100 else "")

    def _cv(n):
        if n == 0: return ""
        p = []
        if n >= 10_000_000: p.append(_bt(n // 10_000_000) + " Crore");  n %= 10_000_000
        if n >= 100_000:    p.append(_bt(n // 100_000)    + " Lakh");   n %= 100_000
        if n >= 1_000:      p.append(_bt(n // 1_000)      + " Thousand"); n %= 1_000
        if n > 0:           p.append(_bt(n))
        return " ".join(p)

    amount = round(amount, 2)
    rupees = int(amount)
    paise  = round((amount - rupees) * 100)
    words  = (_cv(rupees) or "Zero") + " Rupees"
    if paise:
        words += " and " + _cv(paise) + " Paise"
    return words + " Only"


