    action = request.form.get("action", "verify")

    if action == "set_pin":
        new_pin     = (request.form.get("new_pin")     or "").strip()
        confirm_pin = (request.form.get("confirm_pin") or "").strip()
        if not new_pin:
            return render_template("partner_finance_controls.html",
                                   mode="set_pin", error="PIN cannot be empty.")
        if len(new_pin) < 4:
            return render_template("partner_finance_controls.html",
                                   mode="set_pin", error="PIN must be at least 4 digits.")
        if new_pin != confirm_pin:
            return render_template("partner_finance_controls.html",
                                   mode="set_pin", error="PINs do not match. Please try again.")
        change_pin(FC_PIN_KEY, new_pin)
        session["fc_unlocked"] = True
        return redirect(url_for("partner_finance_controls"))

    else:
        pin = (request.form.get("pin") or "").strip()
        if verify_pin(FC_PIN_KEY, pin):
            session["fc_unlocked"] = True
            return redirect(url_for("partner_finance_controls"))
        return render_template("partner_finance_controls.html",
                               mode="unlock", error="Incorrect PIN. Please try again.")


