@app.route("/partner/billing-advice/view")
@billing_advice_required
def partner_billing_advice_view():
    """HTML view of the Bill Register for a given FY. Ashish-only."""
    is_ashish = (session.get("emp_name") == "Ashish Thatte")
    if not is_ashish:
        return render_template("access_denied.html")

    fy = request.args.get("fy", "").strip()
    if not fy:
        return redirect(url_for("partner_finance_controls"))

    branch = session.get("branch", "")
    if branch:
        switch_branch_db(branch)

    branch_label = session.get("branch_label", branch.capitalize())
    if branch_label.startswith("JAA - "):
        branch_label = branch_label[6:]

    try:
        with get_conn() as conn:
            rows = conn.execute(
                """SELECT ba.id, ba.invoice_no, ba.invoice_date,
                          ba.firm_name, ba.service_desc,
                          ba.professional_fee, ba.tax_type
                   FROM   billing_advice ba
                   WHERE  ba.status = 'finalized' AND ba.fy = ?
                   ORDER  BY ba.invoice_date ASC, ba.invoice_no ASC""", (fy,)
            ).fetchall()
            rows = [dict(r) for r in rows]
            oop_map = {}
            if rows:
                ids = [r["id"] for r in rows]
                ph  = ",".join("?" * len(ids))
                for oor in conn.execute(
                    f"SELECT billing_advice_id, SUM(total) AS t FROM billing_advice_oop "
                    f"WHERE billing_advice_id IN ({ph}) GROUP BY billing_advice_id", ids
                ).fetchall():
                    oop_map[oor["billing_advice_id"]] = float(oor["t"] or 0)
    except Exception as ex:
        import traceback; traceback.print_exc()
        return f"<h2>Error loading bill register</h2><pre>{__import__('traceback').format_exc()}</pre>", 500

    from datetime import datetime as _dtm
    table_rows = []
    grand = {"fee": 0, "oop": 0, "cgst": 0, "sgst": 0, "igst": 0, "total": 0}
    for sr, rec in enumerate(rows, 1):
        raw = (rec.get("invoice_date") or "")[:10]
        try:
            dto      = _dtm.strptime(raw, "%Y-%m-%d")
            date_fmt = dto.strftime("%d-%m-%Y")
        except Exception:
            date_fmt = raw

        fee = float(rec.get("professional_fee") or 0)
        oop = float(oop_map.get(rec["id"], 0))
        tt  = (rec.get("tax_type") or "").upper()
        if "IGST" in tt:
            cgst, sgst, igst = 0.0, 0.0, round(fee * 0.18, 2)
        elif "GST" in tt:
            cgst = sgst = round(fee * 0.09, 2); igst = 0.0
        else:
            cgst = sgst = igst = 0.0

        total = fee + oop + cgst + sgst + igst
        grand["fee"]   += fee;   grand["oop"]  += oop
        grand["cgst"]  += cgst;  grand["sgst"] += sgst
        grand["igst"]  += igst;  grand["total"] += total

        table_rows.append({
            "sr": sr, "invoice_no": rec.get("invoice_no", ""),
            "date": date_fmt, "firm_name": rec.get("firm_name", ""),
            "service_desc": rec.get("service_desc", ""),
            "fee": fee, "oop": oop, "cgst": cgst,
            "sgst": sgst, "igst": igst, "total": total,
        })

    return render_template("partner_bill_register_view.html",
                           fy=fy, branch_label=branch_label,
                           table_rows=table_rows, grand=grand)


