# ── Reimbursement Report ──────────────────────────────────────────────────────

def _get_reimb_fy_list():
    """Return all distinct FYs from finalized billing_advice, latest first."""
    try:
        with get_conn() as conn:
            rows = conn.execute(
                "SELECT DISTINCT fy FROM billing_advice WHERE status='finalized' "
                "ORDER BY fy DESC"
            ).fetchall()
            return [r["fy"] for r in rows if r["fy"]]
    except Exception:
        return []


def _query_reimb_companywise(fy):
    """Return list of dicts grouped by company for a given FY."""
    with get_conn() as conn:
        rows = conn.execute("""
            SELECT
                oop.person_name  AS emp_name,
                oop.role         AS role,
                oop.travel       AS travel,
                oop.refreshment  AS refreshment,
                oop.others       AS others,
                oop.total        AS total,
                ba.invoice_no    AS invoice_no,
                ba.invoice_date  AS invoice_date,
                ba.company_code  AS company_code,
                COALESCE(c.full_name, ba.firm_name, ba.company_code) AS company_name
            FROM billing_advice_oop oop
            JOIN billing_advice ba ON ba.id = oop.billing_advice_id
            LEFT JOIN companies c  ON c.unique_code = ba.company_code
            WHERE ba.status = 'finalized' AND ba.fy = ?
            ORDER BY company_name ASC, ba.invoice_date ASC, oop.person_name ASC
        """, (fy,)).fetchall()
    return [dict(r) for r in rows]


def _query_reimb_consolidated(fy):
    """Return list of dicts aggregated by employee for a given FY."""
    with get_conn() as conn:
        rows = conn.execute("""
            SELECT
                oop.person_name                   AS emp_name,
                oop.role                          AS role,
                SUM(oop.travel)                   AS travel,
                SUM(oop.refreshment)              AS refreshment,
                SUM(oop.others)                   AS others,
                SUM(oop.total)                    AS total,
                COUNT(DISTINCT ba.company_code)   AS num_companies,
                COUNT(DISTINCT ba.id)             AS num_invoices
            FROM billing_advice_oop oop
            JOIN billing_advice ba ON ba.id = oop.billing_advice_id
            WHERE ba.status = 'finalized' AND ba.fy = ?
            GROUP BY oop.person_name, oop.role
            ORDER BY oop.person_name ASC
        """, (fy,)).fetchall()
    return [dict(r) for r in rows]


@app.route("/partner/reimbursement-report")
@billing_advice_required
def partner_reimbursement_report():
    """Reimbursement Report — company-wise or consolidated view."""
    branch = session.get("branch", "")
    if branch:
        switch_branch_db(branch)

    fy_list = _get_reimb_fy_list()
    selected_fy = request.args.get("fy", "").strip() or (fy_list[0] if fy_list else "")
    consolidated = request.args.get("consolidated", "0").strip() == "1"

    company_data = []   # for company-wise
    emp_data     = []   # for consolidated
    grand = {"travel": 0, "refreshment": 0, "others": 0, "total": 0}

    if selected_fy:
        if consolidated:
            emp_data = _query_reimb_consolidated(selected_fy)
            for r in emp_data:
                grand["travel"]       += float(r["travel"] or 0)
                grand["refreshment"]  += float(r["refreshment"] or 0)
                grand["others"]       += float(r["others"] or 0)
                grand["total"]        += float(r["total"] or 0)
        else:
            rows = _query_reimb_companywise(selected_fy)
            # Group by company
            from collections import OrderedDict as _OD
            grp = _OD()
            for r in rows:
                cn = r["company_name"]
                grp.setdefault(cn, {"rows": [], "sub": {"travel":0,"refreshment":0,"others":0,"total":0}})
                grp[cn]["rows"].append(r)
                grp[cn]["sub"]["travel"]       += float(r["travel"] or 0)
                grp[cn]["sub"]["refreshment"]  += float(r["refreshment"] or 0)
                grp[cn]["sub"]["others"]       += float(r["others"] or 0)
                grp[cn]["sub"]["total"]        += float(r["total"] or 0)
                grand["travel"]       += float(r["travel"] or 0)
                grand["refreshment"]  += float(r["refreshment"] or 0)
                grand["others"]       += float(r["others"] or 0)
                grand["total"]        += float(r["total"] or 0)
            company_data = list(grp.items())   # [(company_name, {rows, sub}), ...]

    return render_template("partner_reimbursement_report.html",
                           fy_list=fy_list,
                           selected_fy=selected_fy,
                           consolidated=consolidated,
                           company_data=company_data,
                           emp_data=emp_data,
                           grand=grand)


@app.route("/partner/reimbursement-report/export")
@billing_advice_required
def partner_reimbursement_export():
    """Download reimbursement report as Excel."""
    import io as _io
    from openpyxl import Workbook as _WB
    from openpyxl.styles import Font as _Font, PatternFill as _Fill, \
        Alignment as _Align, Border as _Border, Side as _Side
    from openpyxl.utils import get_column_letter as _gcl

    branch = session.get("branch", "")
    if branch:
        switch_branch_db(branch)

    fy_list = _get_reimb_fy_list()
    fy          = request.args.get("fy", "").strip() or (fy_list[0] if fy_list else "")
    consolidated = request.args.get("consolidated", "0").strip() == "1"

    NAVY    = "1B2A4A"
    LGREY   = "F3F4F6"
    LYELLOW = "FEF9C3"
    NUM_FMT = "#,##0.00"

    def _tb():
        s = _Side(style="thin")
        return _Border(left=s, right=s, top=s, bottom=s)

    def _hdr_cell(ws, row, col, val, bg=NAVY, fg="FFFFFF", bold=True, w=None):
        c = ws.cell(row=row, column=col, value=val)
        c.font      = _Font(bold=bold, color=fg, name="Arial", size=10)
        c.fill      = _Fill("solid", fgColor=bg)
        c.alignment = _Align(horizontal="center", vertical="center", wrap_text=True)
        c.border    = _tb()
        return c

    def _data_cell(ws, row, col, val, num=False, bold=False, bg=None, fg="000000"):
        c = ws.cell(row=row, column=col, value=val)
        c.font   = _Font(bold=bold, color=fg, name="Arial", size=10)
        c.border = _tb()
        if bg:
            c.fill = _Fill("solid", fgColor=bg)
        if num:
            c.number_format = NUM_FMT
            c.alignment     = _Align(horizontal="right")
        return c

    wb = _WB()
    ws = wb.active

    if consolidated:
        ws.title = f"Reimbursement Consolidated {fy}"
        emp_data = _query_reimb_consolidated(fy)

        # Column widths
        for ci, w in enumerate([6,25,18,14,14,14,14,16,14], 1):
            ws.column_dimensions[_gcl(ci)].width = w

        # Title row
        ws.merge_cells("A1:I1")
        tc = ws["A1"]
        tc.value     = f"Reimbursement Report (Consolidated) — {fy}"
        tc.font      = _Font(bold=True, color="FFFFFF", size=13, name="Arial")
        tc.fill      = _Fill("solid", fgColor=NAVY)
        tc.alignment = _Align(horizontal="center", vertical="center")
        ws.row_dimensions[1].height = 22

        # Header row
        hdrs = ["Sr.", "Employee Name", "Role", "Travel (₹)",
                "Refreshment (₹)", "Others (₹)", "Total (₹)",
                "No. of Companies", "No. of Invoices"]
        for ci, h in enumerate(hdrs, 1):
            _hdr_cell(ws, 2, ci, h, bg=LGREY, fg="1B2A4A")
        ws.row_dimensions[2].height = 18

        grand = {"travel":0,"refreshment":0,"others":0,"total":0}
        dr = 3
        for sr, r in enumerate(emp_data, 1):
            _data_cell(ws, dr, 1, sr)
            _data_cell(ws, dr, 2, r["emp_name"])
            _data_cell(ws, dr, 3, r["role"])
            _data_cell(ws, dr, 4, float(r["travel"] or 0), num=True)
            _data_cell(ws, dr, 5, float(r["refreshment"] or 0), num=True)
            _data_cell(ws, dr, 6, float(r["others"] or 0), num=True)
            _data_cell(ws, dr, 7, float(r["total"] or 0), num=True)
            _data_cell(ws, dr, 8, r["num_companies"])
            _data_cell(ws, dr, 9, r["num_invoices"])
            grand["travel"]      += float(r["travel"] or 0)
            grand["refreshment"] += float(r["refreshment"] or 0)
            grand["others"]      += float(r["others"] or 0)
            grand["total"]       += float(r["total"] or 0)
            dr += 1

        # Grand total
        for ci in range(1, 10):
            bg = NAVY
            _data_cell(ws, dr, ci, "", bold=True, bg=bg, fg="FFFFFF")
        ws.cell(row=dr, column=2).value = "Grand Total"
        ws.cell(row=dr, column=2).font  = _Font(bold=True, color="FFFFFF", name="Arial")
        for ci, key in [(4,"travel"),(5,"refreshment"),(6,"others"),(7,"total")]:
            c = ws.cell(row=dr, column=ci)
            c.value = grand[key]; c.number_format = NUM_FMT
            c.font  = _Font(bold=True, color="FFFFFF", name="Arial")
            c.alignment = _Align(horizontal="right")
            c.fill  = _Fill("solid", fgColor=NAVY); c.border = _tb()

        filename = f"reimbursement_consolidated_{fy}.xlsx"

    else:
        ws.title = f"Reimbursement {fy}"
        rows = _query_reimb_companywise(fy)

        from collections import OrderedDict as _OD
        grp = _OD()
        for r in rows:
            cn = r["company_name"]
            grp.setdefault(cn, {"rows":[], "sub":{"travel":0,"refreshment":0,"others":0,"total":0}})
            grp[cn]["rows"].append(r)
            grp[cn]["sub"]["travel"]      += float(r["travel"] or 0)
            grp[cn]["sub"]["refreshment"] += float(r["refreshment"] or 0)
            grp[cn]["sub"]["others"]      += float(r["others"] or 0)
            grp[cn]["sub"]["total"]       += float(r["total"] or 0)

        # Column widths
        for ci, w in enumerate([6,25,18,14,14,14,14,18,14], 1):
            ws.column_dimensions[_gcl(ci)].width = w

        # Title
        ws.merge_cells("A1:I1")
        tc = ws["A1"]
        tc.value     = f"Reimbursement Report (Company-wise) — {fy}"
        tc.font      = _Font(bold=True, color="FFFFFF", size=13, name="Arial")
        tc.fill      = _Fill("solid", fgColor=NAVY)
        tc.alignment = _Align(horizontal="center", vertical="center")
        ws.row_dimensions[1].height = 22

        # Column headers
        hdrs = ["Sr.", "Employee Name", "Role", "Travel (₹)",
                "Refreshment (₹)", "Others (₹)", "Total (₹)",
                "Invoice No", "Invoice Date"]
        for ci, h in enumerate(hdrs, 1):
            _hdr_cell(ws, 2, ci, h, bg=LGREY, fg="1B2A4A")
        ws.row_dimensions[2].height = 18

        grand = {"travel":0,"refreshment":0,"others":0,"total":0}
        dr = 3; sr = 0

        for co_name, co_data in grp.items():
            # Company header row (navy, full width merged)
            ws.merge_cells(f"A{dr}:I{dr}")
            ch = ws.cell(row=dr, column=1, value=f"  {co_name}")
            ch.font      = _Font(bold=True, color="FFFFFF", name="Arial", size=11)
            ch.fill      = _Fill("solid", fgColor=NAVY)
            ch.alignment = _Align(vertical="center")
            ch.border    = _tb()
            ws.row_dimensions[dr].height = 18
            dr += 1

            for r in co_data["rows"]:
                sr += 1
                inv_date = (r.get("invoice_date") or "")[:10]
                _data_cell(ws, dr, 1, sr)
                _data_cell(ws, dr, 2, r["emp_name"])
                _data_cell(ws, dr, 3, r["role"])
                _data_cell(ws, dr, 4, float(r["travel"] or 0), num=True)
                _data_cell(ws, dr, 5, float(r["refreshment"] or 0), num=True)
                _data_cell(ws, dr, 6, float(r["others"] or 0), num=True)
                _data_cell(ws, dr, 7, float(r["total"] or 0), num=True)
                _data_cell(ws, dr, 8, r.get("invoice_no",""))
                _data_cell(ws, dr, 9, inv_date)
                dr += 1

            # Company subtotal
            sub = co_data["sub"]
            for ci in range(1, 10):
                _data_cell(ws, dr, ci, "", bold=True, bg=LYELLOW)
            ws.cell(row=dr, column=2).value = f"{co_name} — Subtotal"
            ws.cell(row=dr, column=2).font  = _Font(bold=True, name="Arial")
            ws.cell(row=dr, column=2).fill  = _Fill("solid", fgColor=LYELLOW)
            for ci, key in [(4,"travel"),(5,"refreshment"),(6,"others"),(7,"total")]:
                c = ws.cell(row=dr, column=ci)
                c.value = sub[key]; c.number_format = NUM_FMT
                c.font  = _Font(bold=True, name="Arial")
                c.alignment = _Align(horizontal="right")
                c.fill  = _Fill("solid", fgColor=LYELLOW); c.border = _tb()
            grand["travel"]      += sub["travel"]
            grand["refreshment"] += sub["refreshment"]
            grand["others"]      += sub["others"]
            grand["total"]       += sub["total"]
            dr += 1

        # Grand total
        for ci in range(1, 10):
            _data_cell(ws, dr, ci, "", bold=True, bg=NAVY, fg="FFFFFF")
        ws.cell(row=dr, column=2).value = "Grand Total"
        ws.cell(row=dr, column=2).font  = _Font(bold=True, color="FFFFFF", name="Arial")
        ws.cell(row=dr, column=2).fill  = _Fill("solid", fgColor=NAVY)
        for ci, key in [(4,"travel"),(5,"refreshment"),(6,"others"),(7,"total")]:
            c = ws.cell(row=dr, column=ci)
            c.value = grand[key]; c.number_format = NUM_FMT
            c.font  = _Font(bold=True, color="FFFFFF", name="Arial")
            c.alignment = _Align(horizontal="right")
            c.fill  = _Fill("solid", fgColor=NAVY); c.border = _tb()

        filename = f"reimbursement_{fy}.xlsx"

    buf = _io.BytesIO(); wb.save(buf); buf.seek(0)
    resp = make_response(buf.read())
    resp.headers["Content-Type"] = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    resp.headers["Content-Disposition"] = f"attachment; filename={filename}"
    return resp


