def _build_task_summary(emp_id: str) -> dict:
    """Build a minimal task summary for the timesheet widget."""
    try:
        tasks   = _jaa.get_tasks_assigned_to(emp_id) if get_tasks_assigned_to else []
        today_s = date.today().isoformat()
        pending  = [t for t in tasks if t["status"] != "Done"]
        overdue  = [t for t in tasks if t["status"] != "Done" and t["due_date"] < today_s]
        return {"pending": len(pending), "overdue": len(overdue)}
    except Exception:
        return {"pending": 0, "overdue": 0}


