@app.route("/partner/tasks")
@partner_required
def partner_tasks():
    branch = session.get("branch")
    if branch:
        switch_branch_db(branch)
    all_tasks    = _jaa.get_all_tasks_for_admin() if get_all_tasks_for_admin else []
    all_cos      = get_all_companies()
    all_emps_raw = get_all_employees()
    # Filter assignable employees based on role
    role     = session.get("role")
    emp_id   = session.get("emp_id")
    emp_role = None
    if role == "user":
        emp_obj  = cur_emp()
        emp_role = emp_obj.get("role") if emp_obj else None
        emp_id   = emp_obj["emp_id"] if emp_obj else emp_id
    if emp_role in ("Associate", "Employee"):
        # Only show direct reports across all companies
        try:
            with get_conn() as conn:
                direct_ids = [r["member_emp_id"] for r in conn.execute(
                    "SELECT DISTINCT member_emp_id FROM company_assignments WHERE reports_to_emp_id=?",
                    (emp_id,)
                ).fetchall()]
            all_emps = [e for e in all_emps_raw if e["emp_id"] in direct_ids]
        except Exception:
            all_emps = all_emps_raw
    else:
        all_emps = all_emps_raw
    today_s      = date.today().isoformat()
    # Filters
    f_company = request.args.get("company", "")
    f_status  = request.args.get("status", "")
    f_emp     = request.args.get("assigned_to", "")
    filtered = all_tasks
    if f_company: filtered = [t for t in filtered if t["company_code"] == f_company]
    if f_status:  filtered = [t for t in filtered if t["status"] == f_status]
    if f_emp:     filtered = [t for t in filtered if t["assigned_to_emp_id"] == f_emp]
    # Group by company
    from collections import defaultdict
    by_co = defaultdict(list)
    for t in filtered:
        by_co[t["company_name"]].append(t)
    tasks_by_company = dict(sorted(by_co.items()))
    return render_template("partner_tasks.html",
        tasks_by_company=tasks_by_company,
        all_tasks=filtered,
        all_cos=all_cos,
        all_emps=all_emps,
        today=today_s,
        f_company=f_company,
        f_status=f_status,
        f_emp=f_emp)


