@app.route("/api/tasks/my-team")
@login_required
def api_tasks_my_team():
    """Return assignable team members for the current user for a given company."""
    role         = session.get("role")
    emp_id       = session.get("emp_id")
    company_code = request.args.get("company", "").strip()
    if not company_code:
        return jsonify({"team": []})

    # Partners / admins — return full company team
    if role in ("partner", "admin", "superadmin"):
        try:
            team    = _jaa.get_company_team(company_code) if get_company_team else []
            members = [m for m in team if m["member_emp_id"] != m.get("partner_emp_id")]
            return jsonify({"team": members})
        except Exception:
            return jsonify({"team": []})

    # Associates / Employees — only their direct reports in this company
    emp_obj = cur_emp()
    if not emp_obj or emp_obj.get("role") not in ("Associate", "Employee"):
        return jsonify({"ok": False, "error": "Unauthorised"}), 403
    emp_id = emp_obj["emp_id"]
    try:
        with get_conn() as conn:
            rows = conn.execute(
                """SELECT ca.member_emp_id, e.full_name AS member_name, e.role AS member_role
                   FROM company_assignments ca
                   JOIN employees e ON e.emp_id = ca.member_emp_id
                   WHERE ca.company_code = ? AND ca.reports_to_emp_id = ?""",
                (company_code, emp_id)
            ).fetchall()
        return jsonify({"team": [dict(r) for r in rows]})
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex), "team": []}), 500


@app.route("/api/tasks/create", methods=["POST"])
@login_required
def api_tasks_create():
    role   = session.get("role")
    emp_id = session.get("emp_id")
    # Partners (session role = partner) can assign to anyone.
    # Associates and Employees (session role = user) can assign to their direct reports only.
    if role not in ("partner", "admin"):
        emp_obj = cur_emp()
        if not emp_obj or emp_obj.get("role") not in ("Associate", "Employee", "Partner"):
            return jsonify({"ok": False, "error": "Only Partners, Associates or Employees can create tasks."})
        emp_id = emp_obj["emp_id"]

    d = request.get_json() or {}
    company_code       = (d.get("company_code") or "").strip()
    title              = (d.get("title") or "").strip()
    description        = (d.get("description") or "").strip()
    assigned_to_emp_id = (d.get("assigned_to_emp_id") or "").strip()
    due_date           = (d.get("due_date") or "").strip()
    task_type          = (d.get("task_type") or "Regular").strip()

    if task_type not in ("Regular", "Emergency", "Specific"):
        task_type = "Regular"

    if not all([company_code, title, assigned_to_emp_id, due_date]):
        return jsonify({"ok": False, "error": "Company, title, assignee and due date are required."})

    # Validate due date — accept both YYYY-MM-DD and DD-MM-YYYY formats
    try:
        if len(due_date) == 10 and due_date[2] == '-' and due_date[5] == '-':
            parts    = due_date.split('-')
            due_date = f"{parts[2]}-{parts[1]}-{parts[0]}"
        due_dt = date.fromisoformat(due_date)
    except (ValueError, IndexError):
        return jsonify({"ok": False, "error": "Invalid due date format. Please select a valid date."})
    if due_dt < date.today():
        return jsonify({"ok": False, "error": "Due date cannot be in the past."})

    # Validate assigned_to is in company_assignments for this company
    try:
        with get_conn() as conn:
            in_team = conn.execute(
                "SELECT id FROM company_assignments WHERE company_code=? AND member_emp_id=?",
                (company_code, assigned_to_emp_id)
            ).fetchone()
        if not in_team:
            return jsonify({"ok": False, "error": "Assignee is not assigned to this company."})
    except Exception:
        pass   # If table missing during migration, allow through

    # For Associates and Employees: restrict to only their direct reports in this company
    if role == "user":
        emp_obj = cur_emp()
        if emp_obj and emp_obj.get("role") in ("Associate", "Employee"):
            with get_conn() as conn:
                under_me = conn.execute(
                    "SELECT id FROM company_assignments "
                    "WHERE company_code=? AND reports_to_emp_id=? AND member_emp_id=?",
                    (company_code, emp_id, assigned_to_emp_id)
                ).fetchone()
            if not under_me:
                return jsonify({"ok": False, "error": "You can only assign tasks to members directly under you in this company."})

    try:
        task_id = _jaa.create_task(company_code, title, description,
                                   emp_id, assigned_to_emp_id, due_date, task_type)
        return jsonify({"ok": True, "task_id": task_id})
    except Exception as ex:
        import traceback; traceback.print_exc()
        return jsonify({"ok": False, "error": f"Failed to create task: {str(ex)}"})


