@app.route("/api/tasks/update-status", methods=["POST"])
@login_required
def api_tasks_update_status():
    emp_id = session.get("emp_id")
    if not emp_id:
        return jsonify({"ok": False, "error": "Not authenticated."})
    d          = request.get_json() or {}
    task_id    = d.get("task_id")
    new_status = (d.get("new_status") or "").strip()
    if not task_id or not new_status:
        return jsonify({"ok": False, "error": "task_id and new_status required."})
    ok = _jaa.update_task_status(int(task_id), new_status, emp_id)
    if not ok:
        return jsonify({"ok": False, "error": "Update failed — task not found or not assigned to you."})
    return jsonify({"ok": True})


