@app.route("/api/reimbursement/submit", methods=["POST"])
@login_required
def api_reimb_submit():
    emp = cur_emp()
    if not emp:
        return jsonify({"ok": False, "error": "Not authenticated."})

    company_code = request.form.get("company_code", "").strip()
    category     = request.form.get("category", "").strip()
    sub_category = request.form.get("sub_category", "").strip() or None
    amount_str   = request.form.get("amount", "").strip()
    description  = request.form.get("description", "").strip()

    # Validate
    if not company_code or not category:
        return jsonify({"ok": False, "error": "Company and category are required."})
    if category not in REIMB_CATEGORIES:
        return jsonify({"ok": False, "error": "Invalid category."})
    if category == "Travel/Conveyance" and not sub_category:
        return jsonify({"ok": False, "error": "Sub-category is required for Travel/Conveyance."})
    try:
        amount = float(amount_str)
        if amount <= 0:
            raise ValueError
    except (ValueError, TypeError):
        return jsonify({"ok": False, "error": "Amount must be greater than 0."})

    # Validate company is in employee's assignments
    try:
        with get_conn() as conn:
            in_co = conn.execute(
                "SELECT id FROM company_assignments WHERE company_code=? AND member_emp_id=?",
                (company_code, emp["emp_id"])
            ).fetchone()
        if not in_co:
            return jsonify({"ok": False, "error": "You are not assigned to this company."})
    except Exception:
        pass  # Allow through if table is missing (new branch)

    # Handle receipt upload
    receipt_path = None
    receipt_file = request.files.get("receipt")
    if receipt_file and receipt_file.filename:
        ext = Path(receipt_file.filename).suffix.lower()
        if ext not in ALLOWED_RECEIPT_EXT:
            return jsonify({"ok": False, "error": "Receipt must be PDF, JPG, or PNG."})
        branch = session.get("branch", "mumbai")
        reimb_dir = DATA_ROOT / branch / "reimbursements" / emp["emp_id"]
        reimb_dir.mkdir(parents=True, exist_ok=True)
        from datetime import datetime as _dt
        ts = _dt.now().strftime("%Y%m%d_%H%M%S")
        safe_name = f"{ts}_{receipt_file.filename.replace(' ', '_')}"
        save_path = reimb_dir / safe_name
        receipt_file.save(str(save_path))
        receipt_path = str(save_path)

    reimb_id = _jaa.submit_reimbursement(
        emp["emp_id"], company_code, category,
        sub_category, amount, description, receipt_path
    )

    # NOTIFICATION HOOK: notify admin of new reimbursement submission
    try:
        co = _jaa.get_company_by_code(company_code)
        co_name = co["full_name"] if co else company_code
        admin_emps = [e for e in _jaa.get_all_employees()
                      if e.get("role") == "Admin" and e.get("status") == "Active"]
        for adm in admin_emps:
            _jaa.create_notification(
                emp_id=adm["emp_id"],
                title="New Reimbursement Submitted",
                message=(f"{emp['full_name']} submitted a reimbursement "
                         f"of \u20b9{amount:,.2f} for {co_name}"),
                notif_type="general",
                reference_id=reimb_id,
                reference_type="reimbursement"
            )
    except Exception:
        pass

    return jsonify({"ok": True, "reimb_id": reimb_id})


@app.route("/reimbursements/receipt/<int:reimbursement_id>")
@login_required
def reimb_receipt(reimbursement_id):
    """Serve receipt file — accessible by submitter, Admin, or Partner."""
    role   = session.get("role")
    emp_id = session.get("emp_id")
    try:
        with get_conn() as conn:
            row = conn.execute(
                "SELECT * FROM reimbursements WHERE id=?", (reimbursement_id,)
            ).fetchone()
    except Exception:
        return "File not found", 404
    if not row:
        return "File not found", 404
    row = dict(row)
    # Access control
    if role not in ("admin", "partner") and row.get("emp_id") != emp_id:
        return "Not authorised", 403
    fp = row.get("receipt_path")
    if not fp or not Path(fp).exists():
        return "File not found on disk", 404
    return send_file(fp, as_attachment=False, download_name=Path(fp).name)


