@app.route("/admin/reimbursements/export")
@admin_required
def admin_reimb_export():
    branch = session.get("branch")
    if branch:
        switch_branch_db(branch)
    all_r = _jaa.get_all_reimbursements_for_admin() if get_all_reimbursements_admin else []
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Reimbursements"
    hdr_fill = PatternFill("solid", fgColor="0D2137")
    hdr_font = Font(color="C9A84C", bold=True, size=11)
    headers  = ["ID", "Employee", "Role", "Company", "Category",
                "Sub-Category", "Amount (₹)", "Description",
                "Status", "Rejection Note", "Submitted At", "Reviewed At", "Reviewed By"]
    for ci, h in enumerate(headers, 1):
        cell = ws.cell(row=1, column=ci, value=h)
        cell.fill = hdr_fill
        cell.font = hdr_font
        cell.alignment = Alignment(horizontal="center")
    for ri, r in enumerate(all_r, 2):
        ws.append([
            r["id"], r.get("emp_name",""), r.get("emp_role",""),
            r.get("company_name",""), r["category"],
            r.get("sub_category","") or "", r["amount"],
            r.get("description","") or "", r["status"],
            r.get("rejection_note","") or "",
            r.get("submitted_at",""), r.get("reviewed_at","") or "",
            r.get("reviewed_by","") or ""
        ])
    for ci in range(1, len(headers)+1):
        max_len = max((len(str(ws.cell(row=r, column=ci).value or ""))
                       for r in range(1, ws.max_row+1)), default=8)
        ws.column_dimensions[get_column_letter(ci)].width = min(max_len+4, 40)
    ws.freeze_panes = "A2"
    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    resp = make_response(buf.read())
    resp.headers["Content-Type"] = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    resp.headers["Content-Disposition"] = "attachment; filename=reimbursements.xlsx"
    return resp


@app.route("/api/reimbursement/approve", methods=["POST"])
@admin_required
def api_reimb_approve():
    d     = request.get_json() or {}
    rid   = d.get("reimbursement_id")
    if not rid:
        return jsonify({"ok": False, "error": "reimbursement_id required."})
    try:
        with get_conn() as conn:
            row = conn.execute("SELECT * FROM reimbursements WHERE id=?", (rid,)).fetchone()
    except Exception:
        return jsonify({"ok": False, "error": "Not found."})
    if not row:
        return jsonify({"ok": False, "error": "Reimbursement not found."})
    row = dict(row)
    ok  = _jaa.approve_reimbursement(int(rid), "Admin") if approve_reimbursement else False
    if not ok:
        return jsonify({"ok": False, "error": "Approval failed."})
    # NOTIFICATION HOOK: notify intern of approval
    try:
        co = _jaa.get_company_by_code(row["company_code"])
        co_name = co["full_name"] if co else row["company_code"]
        _jaa.create_notification(
            emp_id=row["emp_id"],
            title="Reimbursement Approved",
            message=(f"Your reimbursement of \u20b9{row['amount']:,.2f} "
                     f"for {co_name} has been Approved"),
            notif_type="general",
            reference_id=int(rid), reference_type="reimbursement"
        )
    except Exception:
        pass
    return jsonify({"ok": True})


