@app.route("/api/billing/mark-reimbursements-billed", methods=["POST"])
@partner_required
def api_billing_mark_reimb_billed():
    """Mark reimbursements as billed when Partner finalises Billing Advice."""
    d = request.get_json() or {}
    reimb_ids       = d.get("reimbursement_ids", [])
    billing_advice_id = d.get("billing_advice_id")
    if not reimb_ids or not billing_advice_id:
        return jsonify({"ok": False, "error": "reimbursement_ids and billing_advice_id required."})
    count = (_jaa.mark_reimbursements_billed(reimb_ids, billing_advice_id)
             if mark_reimbursements_billed else 0)
    # NOTIFICATION HOOK: notify employees their reimbursement was billed
    try:
        with get_conn() as conn:
            placeholders = ",".join("?" * len(reimb_ids))
            rows = conn.execute(
                f"SELECT r.*, co.full_name AS company_name "
                f"FROM reimbursements r "
                f"JOIN companies co ON co.unique_code = r.company_code "
                f"WHERE r.id IN ({placeholders})",
                reimb_ids
            ).fetchall()
        for row in rows:
            row = dict(row)
            _jaa.create_notification(
                emp_id=row["emp_id"],
                title="Reimbursement Billed",
                message=(f"Your reimbursement of \u20b9{row['amount']:,.2f} "
                         f"for {row['company_name']} has been included in billing"),
                notif_type="general",
                reference_id=row["id"], reference_type="reimbursement"
            )
    except Exception:
        pass
    return jsonify({"ok": True, "updated": count})


