@app.route("/api/partner/add-member", methods=["POST"])
@partner_required
def api_partner_add_member():
    partner_emp_id = session.get("emp_id")
    if not partner_emp_id:
        return jsonify({"ok": False, "error": "Not authenticated."})
    d = request.get_json() or {}
    company_code      = d.get("company_code", "").strip()
    member_emp_id     = d.get("member_emp_id", "").strip()
    reports_to_emp_id = d.get("reports_to_emp_id", "").strip() or None
    if not company_code or not member_emp_id:
        return jsonify({"ok": False, "error": "Company and member required."})
    # All partners can add members to any company — partner_emp_id recorded as audit trail only
    ok = _jaa.add_company_assignment(company_code, partner_emp_id, member_emp_id, reports_to_emp_id)
    if not ok:
        return jsonify({"ok": False, "error": "Member already assigned to this company."})
    # Return updated team immediately so UI can refresh without a second round-trip
    try:
        updated_team = _jaa.get_company_team(company_code) if get_company_team else []
    except Exception:
        updated_team = []
    return jsonify({"ok": True, "team": updated_team})


@app.route("/api/partner/remove-member", methods=["POST"])
@partner_required
def api_partner_remove_member():
    partner_emp_id = session.get("emp_id")
    if not partner_emp_id:
        return jsonify({"ok": False, "error": "Not authenticated."})
    d = request.get_json() or {}
    assignment_id = d.get("assignment_id")
    if not assignment_id:
        return jsonify({"ok": False, "error": "Assignment ID required."})
    # Any partner can remove any member — only block removing their own anchor row
    with get_conn() as conn:
        row = conn.execute(
            "SELECT id, company_code, partner_emp_id, member_emp_id FROM company_assignments WHERE id=?",
            (assignment_id,)
        ).fetchone()
    if not row:
        return jsonify({"ok": False, "error": "Assignment not found."})
    if row["member_emp_id"] == row["partner_emp_id"]:
        return jsonify({"ok": False, "error": "Cannot remove the company anchor row."})
    # Capture company_code BEFORE removing (row will be gone after)
    company_code_for_team = dict(row).get("company_code", "")
    _jaa.remove_company_assignment(assignment_id)
    # Return updated team immediately so UI can refresh without a second round-trip
    try:
        updated_team = _jaa.get_company_team(company_code_for_team) if (get_company_team and company_code_for_team) else []
    except Exception:
        updated_team = []
    return jsonify({"ok": True, "team": updated_team})


