@app.route("/api/billing/save-gstin", methods=["POST"])
@login_required
def api_billing_save_gstin():
    data  = request.get_json() or {}
    name  = (data.get("name", "") or "").strip()
    gstin = (data.get("gstin", "") or "").strip().upper()
    if not name or not DB_READY:
        return jsonify({"ok": False})
    try:
        with get_conn() as conn:
            row = conn.execute(
                "SELECT id FROM companies WHERE LOWER(full_name)=LOWER(?)", (name,)
            ).fetchone()
            if row:
                conn.execute(
                    "UPDATE companies SET gstin=? WHERE LOWER(full_name)=LOWER(?)",
                    (gstin, name)
                )
        return jsonify({"ok": True})
    except Exception as ex:
        return jsonify({"ok": False, "error": str(ex)})

